ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn="everywhere"
fun deconstruct(data,idViabilidad = null) = data map ((item, index) ->
  if (!isEmpty(item.subProductos))
      ([ producto : mappearProducto(item, idViabilidad) ] ++ deconstruct(item.subProductos, idViabilidad))
    else { producto : mappearProducto(item, idViabilidad) })
fun mappearProducto(item, idViabilidad) = {
               "Operacion": item.codigoAccion,
               "QuoteLineItemId": item.idItem,
               "productCode": item.codigo,
               "parentId": item.idRaiz,
               "idOrigen": idViabilidad,
               "ServiceAccId": item.idCuentaServicio,
               "idContacto": do {
                var itemOrder = (vars.orden.resultados[0].items filter ($.idItem == item.idItem))[0]
                ---
                if (itemOrder.idRaiz != null and
                        itemOrder.contactosItem[0].id == null) //Agregado por GO
                    ((vars.orden.resultados[0].items filter ($.idItem == item.idRaiz))[0]).contactosItem[0].id
                else
                    itemOrder.contactosItem[0].id
               },
               "billingAccId": do {
                var itemOrder = (vars.orden.resultados[0].items filter ($.idItem == item.idItem))[0]
                ---
                if (itemOrder.idRaiz != null and
                        itemOrder.idCuentaFacturacion == null) //Agregado por GO
                    ((vars.orden.resultados[0].items filter ($.idItem == item.idRaiz))[0]).idCuentaFacturacion
                else
                    itemOrder.idCuentaFacturacion
               },
               "listaConfiguraciones": item.opciones map {
                            "Quantity": $.cantidadParametros,
                            "parametros": $.parametros map {
                                "atributo": $.codigo,
                                "valor": if ($.valor == "") null else $.valor
                            }
                        }
           }

var listaProductos = if (vars.viabilityResponse.resultados.productos != null) 
        flatten(vars.viabilityResponse.resultados map (item) ->
        	if (item.productos != null) 
        		deconstruct(item.productos, item.idViabilidad)..producto
         else null )
        else null
var listaPaquetes = flatten( if (vars.viabilityResponse.resultados.paquetes != null) 
            vars.viabilityResponse.resultados map (item) -> 
            (item.paquetes map (itemPaq) -> {
                idPaquete: itemPaq.idPaquete,
                listadeProduct: flatten(deconstruct(itemPaq.productos, item.idViabilidad)..producto)
                }) else null)
---
{
    "orderOM": vars.ordenOM,
    "opportunityId": vars.orden.resultados[0].agrupador,
    "masterQuoteNumber": vars.orden.resultados[0].subAgrupador,
    "tipoSolicitud": vars.orden.resultados[0].tipoSolicitud,
    "listadeParametros": flatten(vars.viabilityResponse.resultados map (item, index) -> item.parametros map  
        {
                "codigo": $.codigo,
                "nombre": $.nombre,
                "valor": $.valor,
                "idOrigen": item.idViabilidad
            }),
    (listadeProduct: listaProductos) if (listaProductos != null),
    (listadePaquetes: listaPaquetes.idPaquete distinctBy ($) map (o,i) -> {
        "idPaquete": o,
        "listadeProduct": flatten((listaPaquetes filter $.idPaquete == o).listadeProduct)
    }) if (listaPaquetes != null),
    "listaViabilidad": vars.viabilityResponse.resultados map ((item, index) -> {
        "viabilidad": item.idViabilidad,
        "estadoGestor": item.subEstado,
        "estadoViabilidad": item.estado,
        "faseGestor": item.fase,
        "fechaFinalEstado": item.fecha,
        "ingeniero": item.responsable,
        "correoIngeniero": item.correoIngeniero,
        "aliado": item.aliado,
        "tipoAliado": item.tipoAliado,
        "causal": item.causal,
        "grupoAsignacion": item.grupo,
        "archivos": item.urlsRecursos map {
            "nombre": $.key,
            "idViabilidad": item.idViabilidad,
            "URL": $.value 
        },
        "respuestadeviabilidad": item.resultado,
        "respuestaGestor": item.comentarios,
        "tipodeViabilidad": item.tipo
      })
}

%dw 2.0
output application/xml encoding= "UTF-8"
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns tier http://schemas.datacontract.org/2004/07/Tier.Common
ns ws http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts
---
soapenv#Envelope @("xmlns:tem": "http://tempuri.org/", 
        "xmlns:tier": "http://schemas.datacontract.org/2004/07/Tier.Common", 
        "xmlns:ws":   "http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts"
        ): {
            soapenv#Header: "",
            soapenv#Body: {
                tem#RespuestaTransaccion: {
                    tem#WSRequestHeader: {
                        tier#property: {
                            tier#"Scheme_Services.Property": {
                                tier#name: "?",
                                tier#value: "?"
                            }
                        },
                        tier#system: {
                            tier#correlationId: vars.viabilityResponse.resultados[0].respuestaViabilidad.correlationId,
                            tier#name: "?",
                            tier#processingServer: "?"
                        }
                    },
                    tem#WSRequestBody: {
                        ws#Descripcion: "Los siguientes items presentan errores: " ++  (vars.itemsWithError joinBy(", ")),
                        ws#Fecha: now(),
                        ws#NumeroSolicitud: vars.viabilityResponse.resultados[0].respuestaViabilidad.idViabilidad,
                        ws#OrdenOM: vars.viabilityResponse.resultados[0].respuestaViabilidad.ordenOM,
                        ws#Productos: vars.viabilityResponse.resultados[0].respuestaViabilidad.productos,
                        ws#Resultado: false,
                        ws#TipoSolicitud: vars.orden.resultados[0].tipoSolicitud,
                        ws#TipoSolicitud: "CERRAR"
                    }
                }
            }
        }

%dw 2.0
output application/java
